const catalog = readCatalog();
const request = {service:"studio", action:"book", id:"first", tenant:"orchid",
                 day:"2025-04-02", units:7};

function cli(script, args, cwd) {
  const result = spawnSync(process.execPath,
    [fileURLToPath(new URL(script, import.meta.url)), ...args], {cwd, encoding:"utf8"});
  assert.equal(result.status, 0, result.stderr);
  return JSON.parse(result.stdout);
}

function temporary(t) {
  const path = mkdtempSync(join(tmpdir(), "studio-quota-"));
  t.after(() => rmSync(path, {recursive:true, force:true}));
  return path;
}

test("Studio uses tenant/day allocation and preserves ledger replay semantics", () => {
  const dispatch = planner(catalog);
  assert.deepEqual(dispatch(request), {status:"booked", id:"first", remaining:1});
  assert.equal(dispatch(request).status, "replay");
  assert.equal(dispatch({...request, units:6}).status, "conflict");
  assert.deepEqual(dispatch({...request, id:"overflow", units:2}),
                   {status:"full", id:"overflow", remaining:1});
  assert.equal(dispatch({...request, id:"last", units:1}).remaining, 0);
  assert.equal(dispatch({...request, id:"tomorrow", day:"2025-04-03"}).status, "booked");
  assert.equal(dispatch({...request, id:"iris", tenant:"iris", units:6}).status, "full");
  assert.equal(dispatch({...request, id:"iris", tenant:"iris", units:5}).status, "booked");
  assert.equal(dispatch({service:"studio", action:"cancel", id:"first"}).status, "cancelled");
  assert.equal(dispatch(request).status, "cancelled");
  assert.equal(dispatch({...request, units:6}).status, "conflict");
  assert.equal(dispatch({service:"studio", action:"cancel", id:"first"}).status, "replay");
  assert.equal(dispatch({...request, id:"replacement"}).remaining, 0);
  assert.deepEqual(dispatch({service:"studio", action:"usage", tenant:"orchid", day:request.day}),
                   {units:8});
  assert.equal(dispatch({service:"studio", action:"summary"}).events.length, 6);
});

test("renewals use Studio admission, inherit tenant, and retain replay/cancel behavior", () => {
  const dispatch = planner(catalog);
  dispatch(request);
  const renewal = {service:"studio", action:"renew", previous:"first", id:"next",
                   day:"2025-05-02", tenant:"iris"};
  assert.deepEqual(dispatch(renewal), {status:"booked", id:"next", remaining:1});
  assert.equal(dispatch(renewal).status, "replay");
  assert.equal(dispatch({...renewal, units:6}).status, "conflict");
  assert.equal(dispatch({...renewal, id:"too-much", units:2}).status, "full");
  dispatch({service:"studio", action:"cancel", id:"next"});
  assert.equal(dispatch(renewal).status, "cancelled");
  dispatch({service:"studio", action:"cancel", id:"first"});
  assert.deepEqual(dispatch({...renewal, id:"missing"}), {status:"missing", id:"first"});
  dispatch({...request, id:"iris", tenant:"iris", units:5});
  assert.equal(dispatch({...renewal, previous:"iris", id:"iris-next", units:6}).status, "full");
});

test("custom allocations, imports and Archive retain separate accounting", () => {
  const dispatch = planner({default:5, studios:new Map([["orchid", 3], ["iris", 9]])});
  assert.equal(dispatch({...request, units:4}).status, "full");
  assert.equal(dispatch({...request, id:"iris", tenant:"iris", units:9}).status, "booked");
  assert.equal(dispatch({...request, service:"archive", units:6}).status, "full");
  assert.equal(dispatch({...request, service:"archive", units:5}).status, "booked");
  assert.equal(dispatch({service:"archive", action:"renew", previous:"first", id:"next",
