      {service:"studio", action:"renew", previous:"first", id:"renewed", day:"2025-04-02"},
      {service:"studio", action:"cancel", id:"first"},
      {...request, id:"cancelled", day:"2025-04-03", units:8},
      {service:"studio", action:"cancel", id:"cancelled"},
